    // ---- Pannes du module (hors des résultats attendus, mais à traiter) ----------------------------------

    [Property(Replay = "42,1", MaxTest = 200)]
    public void Panne_EnRetrait_SArreteAussitot_RendLesBilletsDejaSortis_SansFraisNiDebit(RetraitEnPanne p)
